      },
    )

    // Mock the LLM stream to return a response that doesn't end the turn
    spyOn(aisdk, 'promptAiSdkStream').mockImplementation(async function* () {
      yield 'Continuing with the analysis...' // Non-empty response, no tool calls
    })

