import { MAX_AGENT_STEPS_DEFAULT } from '@codebuff/common/constants/agents'
import { mainPrompt } from './main-prompt'

import type { MainPromptOptions } from './main-prompt'
import type { ClientToolCall } from './tools/constants'
import type { ClientAction } from '@codebuff/common/actions'
import type {
  SessionState,
  ToolResult,
} from '@codebuff/common/types/session-state'
import type { WebSocket } from 'ws'

export async function loopMainPrompt(
  ws: WebSocket,
  action: ClientAction<'prompt'>,
  options: MainPromptOptions & { maxIterations?: number },
): Promise<{
  sessionState: SessionState
  toolCalls: Array<ClientToolCall>
  toolResults: Array<ToolResult>
}> {
  const maxIterations = options.maxIterations ?? MAX_AGENT_STEPS_DEFAULT
  let { sessionState, toolResults, toolCalls } = await mainPrompt(
    ws,
    action,
    options,
  )
  let iterations = 0
  // Continue running as long as the agent is using tools and hasn't decided to end the turn.
  while (
    toolCalls.length > 0 &&
    !toolCalls.some((tc) => tc.toolName === 'end_turn')
  ) {
    const nextAction: ClientAction<'prompt'> = {
      ...action,
      sessionState,
      toolResults,
      prompt: undefined,
    }
    const result = await mainPrompt(ws, nextAction, options)
    sessionState = result.sessionState
    toolResults = result.toolResults
    toolCalls = result.toolCalls
    iterations++
    if (iterations >= maxIterations) {
      break
    }
  }

  return { sessionState, toolCalls, toolResults }
}

import { renderToolResults } from '@codebuff/common/tools/utils'
import { AgentTemplateTypes } from '@codebuff/common/types/session-state'
import { generateCompactId } from '@codebuff/common/util/string'
import { uniq } from 'lodash'

import { checkTerminalCommand } from './check-terminal-command'
import { loopAgentSteps } from './run-agent-step'
import { getAgentTemplate } from './templates/agent-registry'
import { logger } from './util/logger'
import { expireMessages } from './util/messages'
import { requestToolCall } from './websockets/websocket-action'

import type { AgentTemplate } from './templates/types'
import type { ClientToolCall } from './tools/constants'
import type { ClientAction } from '@codebuff/common/actions'
import type { CostMode } from '@codebuff/common/old-constants'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type {
  SessionState,
  ToolResult,
  AgentTemplateType,
} from '@codebuff/common/types/session-state'
import type { WebSocket } from 'ws'

export interface MainPromptOptions {
  userId: string | undefined
  clientSessionId: string
  onResponseChunk: (chunk: string | PrintModeEvent) => void
  localAgentTemplates: Record<string, AgentTemplate>
}

export const mainPrompt = async (
  ws: WebSocket,
  action: ClientAction<'prompt'>,
  options: MainPromptOptions,
): Promise<{
  sessionState: SessionState
  toolCalls: Array<ClientToolCall>
  toolResults: Array<ToolResult>
}> => {
  const { userId, clientSessionId, onResponseChunk, localAgentTemplates } =
    options

  const {
    prompt,
    sessionState: sessionState,
    fingerprintId,
    costMode,
    promptId,
    agentId,
    promptParams,
  } = action
  const { fileContext, mainAgentState } = sessionState

  if (prompt) {
    // Check if this is a direct terminal command
    const startTime = Date.now()
    const terminalCommand = await checkTerminalCommand(prompt, {
      clientSessionId,
      fingerprintId,
      userInputId: promptId,
      userId,
    })
    const duration = Date.now() - startTime

    if (terminalCommand) {
      logger.debug(
        {
          duration,
          prompt,
        },
        `Detected terminal command in ${duration}ms, executing directly: ${prompt}`,
      )

      const response = await requestToolCall(
        ws,
        promptId,
        'run_terminal_command',
        {
          command: terminalCommand,
          mode: 'user',
          process_type: 'SYNC',
          timeout_seconds: -1,
        },
      )

      const toolResult: ToolResult['output'] = {
        type: 'text',
        value:
          (response.success ? response.output?.value : response.error) || '',
      }
      if (response.success) {
        mainAgentState.messageHistory.push({
          role: 'user',
          content: renderToolResults([
            {
              toolName: 'run_terminal_command',
              toolCallId: generateCompactId(),
              output: toolResult,
            },
          ]),
        })
      }

      const newSessionState = {
        ...sessionState,
        messageHistory: expireMessages(
          mainAgentState.messageHistory,
          'userPrompt',
        ),
      }

      return {
        sessionState: newSessionState,
