#!/usr/bin/env node

import { type CostMode } from '@codebuff/common/old-constants'
import { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'
import { Command, Option } from 'commander'
import { red, yellow, bold } from 'picocolors'

import { displayLoadedAgents, loadLocalAgents } from './agents/load-agents'
import { CLI } from './cli'
import { cliArguments, cliOptions } from './cli-definitions'
import { handlePublish } from './cli-handlers/publish'
import { npmAppVersion, backendUrl } from './config'
import { createTemplateProject } from './create-template-project'
import { printModeLog, setPrintMode } from './display/print-mode'
import { enableSquashNewlines } from './display/squash-newlines'
import { loadCodebuffConfig } from './json-config/parser'
import {
  getProjectRoot,
  getWorkingDirectory,
  initializeProjectRootAndWorkingDir,
  initProjectFileContextWithWorker,
} from './project-files'
import { rageDetectors } from './rage-detectors'
import { logAndHandleStartup } from './startup-process-handler'
import { recreateShell } from './terminal/run-command'
import { validateAgentDefinitionsIfAuthenticated } from './utils/agent-validation'
import { createAuthHeaders } from './utils/auth-headers'
import { initAnalytics, trackEvent } from './utils/analytics'
import { logger } from './utils/logger'
import { Spinner } from './utils/spinner'

import type { CliOptions } from './types'

export async function validateAgent(
  agent: string,
  localAgents?: Record<string, any>,
): Promise<void> {
  const agents = localAgents ?? {}

  // if local agents are loaded, they're already validated
  if (
    !!agents?.[agent] ||
    !!Object.values(agents ?? {}).find((a: any) => a?.displayName === agent)
  )
    return

  Spinner.get().start('Checking agent...')
  try {
    const url = `${backendUrl}/api/agents/validate-name?agentId=${encodeURIComponent(agent)}`

    // Use helper to create headers with x-codebuff-api-key
    const headers = createAuthHeaders()

    const resp = await fetch(url, {
      method: 'GET',
      headers,
    })
    const data: { valid?: boolean } = await resp.json().catch(() => ({}) as any)

    if (resp.ok && data.valid) return

    if (resp.ok && !data.valid) {
      console.error(red(`\nUnknown agent: ${bold(agent)}. Exiting.`))
      process.exit(1)
    }
  } catch {
    console.error(
      yellow(
        `\nCould not validate agent due to a network error. Proceeding...`,
      ),
    )
  } finally {
    Spinner.get().stop()
  }
}

async function codebuff({
  initialInput,
  git,
  costMode,
  runInitFlow,
  model,
  agent,
  params,
  print,
  cwd,
  trace,
}: CliOptions) {
  enableSquashNewlines()
  const workingDir = getWorkingDirectory()
  const projectRoot = getProjectRoot()
  await recreateShell(workingDir)

  // Kill all processes we failed to kill before
  const processCleanupPromise = logAndHandleStartup()

  initAnalytics()
  rageDetectors.startupTimeDetector.start()

  const initFileContextPromise = initProjectFileContextWithWorker(projectRoot)

  // Load local agents, display them, then validate agent using preloaded agents
  const loadAgentsAndDisplayPromise = loadLocalAgents({ verbose: true }).then(
    (agents) => {
      validateAgentDefinitionsIfAuthenticated(Object.values(agents))

      const codebuffConfig = loadCodebuffConfig()
      displayLoadedAgents(codebuffConfig)

      return agents // pass along for next step
    },
  )

  // Ensure validation runs strictly after local agent load/display
  const loadAndValidatePromise: Promise<void> =
    loadAgentsAndDisplayPromise.then(async (agents) => {
      // Only validate if agent is specified
      if (!agent) {
        return
      }
      await validateAgent(agent, agents)
    })

  const readyPromise = Promise.all([
    initFileContextPromise,
    processCleanupPromise,
    loadAndValidatePromise,
  ])

  // Initialize the CLI singleton
  CLI.initialize(readyPromise, {
    git,
    costMode,
    model,
    agent,
    params,
    print,
    trace,
  })

  const cli = CLI.getInstance()
  await cli.printInitialPrompt({ initialInput, runInitFlow })

  rageDetectors.startupTimeDetector.end()
}

if (require.main === module) {
  const program = new Command()

  program.name('codebuff').version(npmAppVersion || '0.0.0')

  // Add arguments from shared definitions
  cliArguments.forEach((arg) => {
    // For hidden arguments, just skip adding them to the help text
    if (!arg.hidden) {
      program.argument(arg.flags, arg.description)
    }
  })

  // Add options from shared definitions
  cliOptions.forEach((opt) => {
    const optionInstance = new Option(opt.flags, opt.description)
    if (opt.hidden) {
      optionInstance.hideHelp(true)
    }
    program.addOption(optionInstance)
  })

  program.addHelpText(
    'after',
    `
Examples:
  $ codebuff                                  # Start in current directory
  $ codebuff -p "tell me about the codebase"  # Print mode (non-interactive)
  $ codebuff --cwd my-project                 # Start in specific directory
  $ codebuff --trace                          # Enable subagent trace logging to .agents/traces/*.log
  $ codebuff --create nextjs my-app           # Create and scaffold a new Next.js project
  $ codebuff publish my-agent                 # Publish agent template to store
  $ codebuff --agent file-picker "find relevant files for authentication"
  $ codebuff --agent reviewer --params '{"focus": "security"}' "review this code"

For all commands and options, run 'codebuff' and then type 'help'.
`,
  )

  program.parse()

  const options = program.opts()
  const args = program.args // Handle template creation

  // Initialize project root and working directory
  initializeProjectRootAndWorkingDir(options.cwd)

  if (options.create) {
    const template = options.create
    const projectDir = args[0] || '.'
    const projectName = args[1] || template
    createTemplateProject(template, projectDir, projectName)
    process.exit(0)
  }

  // Handle publish command
  if (args[0] === 'publish') {
    const agentNames = args.slice(1)
    await handlePublish(agentNames)
    process.exit(0)
  }

  // Handle deprecated --pro flag
  if (options.pro) {
    console.error(
      red(
        'Warning: The --pro flag is deprecated. Please restart codebuff and use the --max option instead.',
      ),
    )
    logger.error(
      {
        errorMessage:
          'The --pro flag is deprecated. Please restart codebuff and use the --max option instead.',
      },
      'Deprecated --pro flag used',
    )
    process.exit(1)
  }

  // Determine cost mode
  let costMode: CostMode = 'normal'
  if (options.lite) {
    costMode = 'lite'
  } else if (options.max) {
    costMode = 'max'
  } else if (options.experimental) {
    costMode = 'experimental'
  } else if (options.ask) {
    costMode = 'ask'
  }

  // Handle git integration
  const git = options.git === 'stage' ? ('stage' as const) : undefined

  // Validate print mode requirements
  if (options.print) {
    const hasPrompt = args.length > 0
    const hasParams = options.params

    setPrintMode(true)
    trackEvent(AnalyticsEvent.PRINT_MODE, {
      args,
      options,
    })

    if (!hasPrompt && !hasParams) {
      printModeLog({
        type: 'error',
        message: 'Error: Print mode requires a prompt to be set',
      })
      process.exit(1)
    }
  }

  // Parse agent params if provided
  let parsedAgentParams: Record<string, any> | undefined
  if (options.params) {
    try {
      parsedAgentParams = JSON.parse(options.params)
    } catch (error) {
      console.error(red(`Error parsing --params JSON: ${error}`))
      process.exit(1)
    }
  }

  // Remove the first argument if it's the compiled binary path which bun weirdly injects (starts with /$bunfs)
  const filteredArgs = args[0]?.startsWith('/$bunfs') ? args.slice(1) : args

  // If first arg is a command like 'publish', don't treat it as initial input
  const isCommand = filteredArgs[0] === 'publish'
  const initialInput = isCommand ? '' : filteredArgs.join(' ')

  codebuff({
    initialInput,
    git,
    costMode,
    runInitFlow: options.init,
    model: options.model,
    agent: options.agent,
    params: parsedAgentParams,
    print: options.print,
    cwd: options.cwd,
    trace: options.trace,
  })
}

import { getUserCredentials } from '../credentials'
import { API_KEY_ENV_VAR } from '@codebuff/common/old-constants'

/**
 * Get the auth token from user credentials or environment variable
 */
export function getAuthToken(): string | undefined {
  const userCredentials = getUserCredentials()
  return userCredentials?.authToken || process.env[API_KEY_ENV_VAR]
}

/**
 * Create headers with x-codebuff-api-key for API requests
 */
export function createAuthHeaders(contentType = 'application/json'): Record<string, string> {
  const headers: Record<string, string> = {
    'Content-Type': contentType,
  }

  const authToken = getAuthToken()
  if (authToken) {
    headers['x-codebuff-api-key'] = authToken
  }

  return headers
}

/**
 * Add x-codebuff-api-key to existing headers
 */
export function addAuthHeader(
  headers: Record<string, string>,
  authToken?: string,
): Record<string, string> {
  const token = authToken || getAuthToken()
  if (token) {
    return {
      ...headers,
      'x-codebuff-api-key': token,
    }
  }
  return headers
}

import { AGENT_PERSONAS } from '@codebuff/common/constants/agents'
import {
  describe,
  it,
  expect,
  beforeEach,
  afterEach,
  spyOn,
  mock,
} from 'bun:test'

import * as agentRegistry from '../../templates/agent-registry'
import { validateAgentNameHandler } from '../agents'

import type {
  Request as ExpressRequest,
  Response as ExpressResponse,
  NextFunction,
} from 'express'

function createMockReq(query: Record<string, any>): Partial<ExpressRequest> {
  return { query } as any
}

function createMockRes() {
  const res: Partial<ExpressResponse> & {
    statusCode?: number
    jsonPayload?: any
  } = {}
  res.status = mock((code: number) => {
    res.statusCode = code
    return res as ExpressResponse
  }) as any
  res.json = mock((payload: any) => {
    res.jsonPayload = payload
    return res as ExpressResponse
  }) as any
  return res as ExpressResponse & { statusCode?: number; jsonPayload?: any }
}

const noopNext: NextFunction = () => {}

describe('validateAgentNameHandler', () => {
  const builtinAgentId = Object.keys(AGENT_PERSONAS)[0] || 'file-picker'

  beforeEach(() => {
    mock.restore()
  })

  afterEach(() => {
    mock.restore()
  })

  it('returns valid=true for builtin agent ids', async () => {
    const req = createMockReq({ agentId: builtinAgentId })
    const res = createMockRes()

    await validateAgentNameHandler(req as any, res as any, noopNext)

    expect(res.status).toHaveBeenCalledWith(200)
    expect(res.json).toHaveBeenCalled()
    expect(res.jsonPayload.valid).toBe(true)
    expect(res.jsonPayload.source).toBe('builtin')
    expect(res.jsonPayload.normalizedId).toBe(builtinAgentId)
  })

  it('returns valid=true for published agent ids (publisher/name)', async () => {
    const agentId = 'codebuff/file-explorer'

    const spy = spyOn(agentRegistry, 'getAgentTemplate')
    spy.mockResolvedValueOnce({ id: 'codebuff/file-explorer@0.0.1' } as any)

    const req = createMockReq({ agentId })
    const res = createMockRes()

    await validateAgentNameHandler(req as any, res as any, noopNext)

    expect(spy).toHaveBeenCalledWith(agentId, {})
    expect(res.status).toHaveBeenCalledWith(200)
    expect(res.jsonPayload.valid).toBe(true)
    expect(res.jsonPayload.source).toBe('published')
    expect(res.jsonPayload.normalizedId).toBe('codebuff/file-explorer@0.0.1')
  })

  it('returns valid=true for versioned published agent ids (publisher/name@version)', async () => {
    const agentId = 'codebuff/file-explorer@0.0.1'

    const spy = spyOn(agentRegistry, 'getAgentTemplate')
    spy.mockResolvedValueOnce({ id: agentId } as any)

    const req = createMockReq({ agentId })
    const res = createMockRes()

    await validateAgentNameHandler(req as any, res as any, noopNext)

    expect(spy).toHaveBeenCalledWith(agentId, {})
    expect(res.status).toHaveBeenCalledWith(200)
    expect(res.jsonPayload.valid).toBe(true)
    expect(res.jsonPayload.source).toBe('published')
    expect(res.jsonPayload.normalizedId).toBe(agentId)
  })

  it('returns valid=false for unknown agents', async () => {
    const agentId = 'someorg/not-a-real-agent'

    const spy = spyOn(agentRegistry, 'getAgentTemplate')
    spy.mockResolvedValueOnce(null)

    const req = createMockReq({ agentId })
    const res = createMockRes()

    await validateAgentNameHandler(req as any, res as any, noopNext)

    expect(spy).toHaveBeenCalledWith(agentId, {})
    expect(res.status).toHaveBeenCalledWith(200)
    expect(res.jsonPayload.valid).toBe(false)
  })

  it('returns 400 for invalid requests (missing agentId)', async () => {
    const req = createMockReq({})
    const res = createMockRes()

    await validateAgentNameHandler(req as any, res as any, noopNext)

    // Handler normalizes zod errors to 400
    expect(res.status).toHaveBeenCalledWith(400)
    expect(res.jsonPayload.valid).toBe(false)
    expect(res.jsonPayload.message).toBe('Invalid request')
  })
})

import { z } from 'zod/v4'
import type {
  Request as ExpressRequest,
  Response as ExpressResponse,
  NextFunction,
} from 'express'
import { logger } from '../util/logger'
import { AGENT_PERSONAS } from '@codebuff/common/constants/agents'
import { getAgentTemplate } from '../templates/agent-registry'

// Add short-lived cache for positive validations
const AGENT_VALIDATION_CACHE_TTL_MS = 5 * 60 * 1000 // 5 minutes

type CacheEntry = {
  result: { valid: true; source?: string; normalizedId?: string }
  expiresAt: number
}

const agentValidationCache = new Map<string, CacheEntry>()

// Simple request schema
const validateAgentRequestSchema = z.object({
  agentId: z.string().min(1),
})

// GET /api/agents/validate-name
export async function validateAgentNameHandler(
  req: ExpressRequest,
  res: ExpressResponse,
  next: NextFunction,
): Promise<void | ExpressResponse> {
  try {
    // Log authentication headers if present (for debugging)
    const hasAuthHeader = !!req.headers.authorization
    const hasApiKey = !!req.headers['x-api-key']

    if (hasAuthHeader || hasApiKey) {
      logger.info(
        { 
          hasAuthHeader,
          hasApiKey,
          agentId: req.query.agentId,
        },
        'Agent validation request with authentication',
      )
    }

    // Parse from query instead (GET)
    const { agentId } = validateAgentRequestSchema.parse({
      agentId: String((req.query as any)?.agentId ?? ''),
    })

    // Check cache (positive results only)
    const cached = agentValidationCache.get(agentId)
    if (cached && cached.expiresAt > Date.now()) {
      return res.status(200).json({ ...cached.result, cached: true })
    } else if (cached) {
      agentValidationCache.delete(agentId)
    }

    // Check built-in agents first
    if (AGENT_PERSONAS[agentId as keyof typeof AGENT_PERSONAS]) {
      const result = { valid: true as const, source: 'builtin', normalizedId: agentId }
      agentValidationCache.set(agentId, {
        result,
        expiresAt: Date.now() + AGENT_VALIDATION_CACHE_TTL_MS,
      })
      return res.status(200).json(result)
    }

    // Check published agents (database)
    const found = await getAgentTemplate(agentId, {})
    if (found) {
      const result = {
        valid: true as const,
        source: 'published',
        normalizedId: found.id,
      }
      agentValidationCache.set(agentId, {
        result,
        expiresAt: Date.now() + AGENT_VALIDATION_CACHE_TTL_MS,
      })
      return res.status(200).json(result)
    }

    return res.status(200).json({ valid: false })
  } catch (error) {
    logger.error(
      { error: error instanceof Error ? error.message : String(error) },
      'Error validating agent name',
    )
    if (error instanceof z.ZodError) {
      return res.status(400).json({ valid: false, message: 'Invalid request', issues: error.issues })
    }
    next(error)
    return
  }
}

