import type {
  AgentDefinition,
  AgentStepContext,
} from '../types/agent-definition'

const definition: AgentDefinition = {
  id: 'diff-reviewer-2',
  displayName: 'Diff Reviewer (Level 2)',
  model: 'anthropic/claude-4-sonnet-20250522',

  inputSchema: {
    prompt: {
      type: 'string',
      description:
        'Please provide a short description of the changes you want to review',
    },
  },
  toolNames: ['read_files', 'run_terminal_command'],

  spawnPurposePrompt:
    'Spawn when you need to review code changes in the git diff',

  systemPrompt:
    'You are an expert software developer. Your job is to review code changes and provide helpful feedback.',

  instructionsPrompt: `Execute the following steps:
1. Run git diff
2. Read the files that have changed
3. Review the changes and suggest improvements

Use the following guidelines while reviewing the changes:
- Find ways to simplify the code
- Reuse existing code as much as possible instead of writing new code
- Preserve as much behavior as possible in the existing code
- Prefer changing as few lines of code as possible
- Look for opportunities to improve the code's readability
- Look for logical errors in the code
- Look for missed cases in the code
- Look for any other bugs`,

  handleSteps: function* ({ agentState, prompt, params }: AgentStepContext) {
    // Step 1: Run git diff immediately. Saves the agent a step, lowering cost and latency!
    yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git diff',
      },
    }

    // Step 2: Let AI run the rest of the steps!
    yield 'STEP_ALL'
  },
}

export default definition

import type {
  AgentDefinition,
  AgentStepContext,
} from '../types/agent-definition'

const definition: AgentDefinition = {
  id: 'diff-reviewer-3',
  displayName: 'Diff Reviewer (Level 3)',
  model: 'anthropic/claude-4-sonnet-20250522',
  inputSchema: {
    prompt: {
      type: 'string',
      description:
        'Please provide a short description of the changes you want to review',
    },
  },
  outputMode: 'last_message',

  toolNames: ['read_files', 'run_terminal_command', 'spawn_agents'],
  spawnableAgents: ['codebuff/file-explorer@0.0.1'],

  spawnPurposePrompt:
    'Spawn when you need to review code changes in the git diff',

  systemPrompt:
    'You are an expert software developer. Your job is to review code changes and provide helpful feedback.',

  instructionsPrompt: `Review the changes and suggest improvements.

Use the following guidelines while reviewing the changes:
- Find ways to simplify the code
- Reuse existing code as much as possible instead of writing new code
- Preserve as much behavior as possible in the existing code
- Prefer changing as few lines of code as possible
- Look for opportunities to improve the code's readability
- Look for logical errors in the code
- Look for missed cases in the code
- Look for any other bugs`,

  handleSteps: function* ({ agentState, prompt, params }: AgentStepContext) {
    // Step 1: Get list of changed files from git diff --name-only
    const { toolResult: gitDiffFilesResult } = yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git diff --name-only',
      },
    }

    // Then, extract file paths from the result
    const changedFiles = (gitDiffFilesResult || '')
      .split('\n')
      .map((line) => line.trim())
      .filter((line) => line && !line.startsWith('??') && !line.includes('OSC'))

    // Step 2: Read the files
    if (changedFiles.length > 0) {
      yield {
        toolName: 'read_files',
        args: {
          paths: changedFiles,
        },
      }
    }

    // Step 3: Run full git diff to see the actual changes
    yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git diff',
      },
    }

    // Step 4: Put words in the AI's mouth to get it to spawn the file explorer.
    yield {
      toolName: 'add_message',
      args: {
        role: 'assistant',
        content:
          'Now I will spawn a file explorer to find any missing codebase context, and then review the changes.',
      },
    }

    yield 'STEP_ALL'
  },
}

export default definition

/**
 * Codebuff Agent Type Definitions
 *
 * This file provides TypeScript type definitions for creating custom Codebuff agents.
 * Import these types in your agent files to get full type safety and IntelliSense.
 *
 * Usage in .agents/your-agent.ts:
 *   import { AgentDefinition, ToolName, ModelName } from './types/agent-definition'
 *
 *   const definition: AgentDefinition = {
 *     // ... your agent configuration with full type safety ...
 *   }
 *
 *   export default definition
 */

// ============================================================================
// Agent Definition and Utility Types
// ============================================================================

export interface AgentDefinition {
  /** Unique identifier for this agent. Must contain only lowercase letters, numbers, and hyphens, e.g. 'code-reviewer' */
  id: string

  /** Version string (if not provided, will default to '0.0.1' and be bumped on each publish) */
  version?: string

  /** Publisher ID for the agent. Must be provided if you want to publish the agent. */
  publisher?: string

  /** Human-readable name for the agent */
  displayName: string

  /** AI model to use for this agent. Can be any model in OpenRouter: https://openrouter.ai/models */
  model: ModelName

  // ============================================================================
  // Tools and Subagents
  // ============================================================================

  /** Tools this agent can use. */
  toolNames?: ToolName[]

  /** Other agents this agent can spawn, like 'codebuff/file-picker@0.0.1'.
   *
   * Use the fully qualified agent id from the agent store, including publisher and version: 'codebuff/file-picker@0.0.1'
   * (publisher and version are required!)
   *
   * Or, use the agent id from a local agent file in your .agents directory: 'file-picker'.
   */
  spawnableAgents?: string[]

  // ============================================================================
  // Input and Output
  // ============================================================================

  /** The input schema required to spawn the agent. Provide a prompt string and/or a params object or none.
   * 80% of the time you want just a prompt string with a description:
   * inputSchema: {
   *   prompt: { type: 'string', description: 'A description of what info would be helpful to the agent' }
   * }
   */
  inputSchema?: {
    prompt?: { type: 'string'; description?: string }
    params?: JsonSchema
  }

  /** Whether to include conversation history from the parent agent in context.
   *
   * Defaults to false.
   * Use this if the agent needs to know all the previous messages in the conversation.
   */
  includeMessageHistory?: boolean

  /** How the agent should output a response to its parent (defaults to 'last_message')
   *
   * last_message: The last message from the agent, typcically after using tools.
   *
   * all_messages: All messages from the agent, including tool calls and results.
   *
   * json: Make the agent output a JSON object. Can be used with outputSchema or without if you want freeform json output.
   */
  outputMode?: 'last_message' | 'all_messages' | 'structured_output'

  /** JSON schema for structured output (when outputMode is 'structured_output') */
  outputSchema?: JsonSchema

  // ============================================================================
  // Prompts
  // ============================================================================

  /** Prompt for when and why to spawn this agent. Include the main purpose and use cases.
   *
   * This field is key if the agent is intended to be spawned by other agents. */
  spawnPurposePrompt?: string

  /** Background information for the agent. Fairly optional. Prefer using instructionsPrompt for agent instructions. */
  systemPrompt?: string

  /** Instructions for the agent.
   *
   * IMPORTANT: Updating this prompt is the best way to shape the agent's behavior.
   * This prompt is inserted after each user input. */
  instructionsPrompt?: string

  /** Prompt inserted at each agent step.
   *
   * Powerful for changing the agent's behavior, but usually not necessary for smart models.
   * Prefer instructionsPrompt for most instructions. */
  stepPrompt?: string

  // ============================================================================
  // Handle Steps
  // ============================================================================

  /** Programmatically step the agent forward and run tools.
   *
   * You can either yield:
   * - A tool call object with toolName and args properties.
   * - 'STEP' to run agent's model and generate one assistant message.
   * - 'STEP_ALL' to run the agent's model until it uses the end_turn tool or stops includes no tool calls in a message.
   *
   * Or use 'return' to end the turn.
   *
   * Example 1:
   * function* handleSteps({ agentStep, prompt, params}) {
   *   const { toolResult } = yield {
   *     toolName: 'read_files',
   *     args: { paths: ['file1.txt', 'file2.txt'] }
   *   }
   *   yield 'STEP_ALL'
   * }
   *
   * Example 2:
   * handleSteps: function* ({ agentState, prompt, params }) {
   *   while (true) {
   *     yield {
   *       toolName: 'spawn_agents',
   *       args: {
   *         agents: [
   *         {
   *           agent_type: 'thinker',
   *           prompt: 'Think deeply about the user request',
   *         },
   *       ],
   *     },
   *   }
   *   yield 'STEP'
   * }
   * }
   */
  handleSteps?: (
    context: AgentStepContext,
  ) => Generator<
    ToolCall | 'STEP' | 'STEP_ALL',
    void,
    { agentState: AgentState; toolResult: string | undefined }
  >
}

// ============================================================================
// Supporting Types
// ============================================================================

export interface AgentState {
  agentId: string
  parentId: string
  messageHistory: Message[]
}

/**
 * Message in conversation history
 */
export interface Message {
  role: 'user' | 'assistant'
  content: string
}

/**
 * Context provided to handleSteps generator function
 */
export interface AgentStepContext {
  agentState: AgentState
  prompt?: string
  params?: Record<string, any>
}

/**
 * Tool call object for handleSteps generator
 */
export type ToolCall<T extends ToolName = ToolName> = {
  [K in T]: {
    toolName: K
    args?: Tools.GetToolParams<K>
  }
}[T]

/**
 * JSON Schema definition (for prompt schema or output schema)
 */
export interface JsonSchema {
  type: string
  properties?: Record<string, any>
  required?: string[]
  [key: string]: any
}

// ============================================================================
// Available Tools
// ============================================================================

/**
 * File operation tools
 */
export type FileTools =
  | 'read_files'
  | 'write_file'
  | 'str_replace'
  | 'find_files'

/**
 * Code analysis tools
 */
export type CodeAnalysisTools = 'code_search' | 'find_files'

/**
 * Terminal and system tools
 */
export type TerminalTools = 'run_terminal_command' | 'run_file_change_hooks'

/**
 * Web and browser tools
 */
export type WebTools = 'web_search' | 'read_docs'

/**
 * Agent management tools
 */
export type AgentTools = 'spawn_agents' | 'set_messages' | 'add_message'

/**
 * Planning and organization tools
 */
export type PlanningTools = 'think_deeply'

/**
 * Output and control tools
 */
export type OutputTools = 'set_output' | 'end_turn'

/**
 * Common tool combinations for convenience
 */
export type FileEditingTools = FileTools | 'end_turn'
export type ResearchTools = WebTools | 'write_file' | 'end_turn'
export type CodeAnalysisToolSet = FileTools | CodeAnalysisTools | 'end_turn'

// ============================================================================
// Available Models (see: https://openrouter.ai/models)
// ============================================================================

/**
 * AI models available for agents. Pick from our selection of recommended models or choose any model in OpenRouter.
 *
 * See available models at https://openrouter.ai/models
 */
export type ModelName =
  // Recommended Models

  // OpenAI
  | 'openai/gpt-5'
  | 'openai/gpt-5-mini'
  | 'openai/gpt-5-nano'

  // Anthropic
  | 'anthropic/claude-4-sonnet-20250522'
  | 'anthropic/claude-opus-4.1'

  // Gemini
  | 'google/gemini-2.5-pro'
  | 'google/gemini-2.5-flash'
  | 'google/gemini-2.5-flash-lite'

  // X-AI
  | 'x-ai/grok-4-07-09'

  // Qwen
  | 'qwen/qwen3-coder'
  | 'qwen/qwen3-coder:fast'
  | 'qwen/qwen3-235b-a22b-2507'
  | 'qwen/qwen3-235b-a22b-2507:fast'
  | 'qwen/qwen3-235b-a22b-thinking-2507'
  | 'qwen/qwen3-235b-a22b-thinking-2507:fast'
  | 'qwen/qwen3-30b-a3b'
  | 'qwen/qwen3-30b-a3b:fast'

  // DeepSeek
  | 'deepseek/deepseek-chat-v3-0324'
  | 'deepseek/deepseek-chat-v3-0324:fast'
  | 'deepseek/deepseek-r1-0528'
  | 'deepseek/deepseek-r1-0528:fast'

  // Other open source models
  | 'moonshotai/kimi-k2'
  | 'moonshotai/kimi-k2:fast'
  | 'z-ai/glm-4.5'
  | 'z-ai/glm-4.5:fast'
  | (string & {})

import type * as Tools from './tools'
export type { Tools }
type ToolName = Tools.ToolName

/**
 * Union type of all available tool names
 */
export type ToolName =
  | 'add_message'
  | 'code_search'
  | 'end_turn'
  | 'find_files'
  | 'read_docs'
  | 'read_files'
  | 'run_file_change_hooks'
  | 'run_terminal_command'
  | 'set_messages'
  | 'set_output'
  | 'spawn_agents'
  | 'str_replace'
  | 'think_deeply'
  | 'web_search'
  | 'write_file'

/**
 * Map of tool names to their parameter types
 */
export interface ToolParamsMap {
  add_message: AddMessageParams
  code_search: CodeSearchParams
  end_turn: EndTurnParams
  find_files: FindFilesParams
  read_docs: ReadDocsParams
  read_files: ReadFilesParams
  run_file_change_hooks: RunFileChangeHooksParams
  run_terminal_command: RunTerminalCommandParams
  set_messages: SetMessagesParams
  set_output: SetOutputParams
  spawn_agents: SpawnAgentsParams
  str_replace: StrReplaceParams
  think_deeply: ThinkDeeplyParams
  web_search: WebSearchParams
  write_file: WriteFileParams
}

/**
 * Add a new message to the conversation history. To be used for complex requests that can't be solved in a single step, as you may forget what happened!
 */
export interface AddMessageParams {
  role: 'user' | 'assistant'
  content: string
}

/**
 * Search for string patterns in the project's files. This tool uses ripgrep (rg), a fast line-oriented search tool. Use this tool only when read_files is not sufficient to find the files you need.
 */
export interface CodeSearchParams {
  /** The pattern to search for. */
  pattern: string
  /** Optional ripgrep flags to customize the search (e.g., "-i" for case-insensitive, "-t ts" for TypeScript files only, "-A 3" for 3 lines after match, "-B 2" for 2 lines before match, "--type-not test" to exclude test files). */
  flags?: string
  /** Optional working directory to search within, relative to the project root. Defaults to searching the entire project. */
  cwd?: string
}

/**
 * End your turn, regardless of any new tool results that might be coming. This will allow the user to type another prompt.
 */
export interface EndTurnParams {}

/**
 * Find several files related to a brief natural language description of the files or the name of a function or class you are looking for.
 */
export interface FindFilesParams {
  /** A brief natural language description of the files or the name of a function or class you are looking for. It's also helpful to mention a directory or two to look within. */
  prompt: string
}

/**
 * Fetch up-to-date documentation for libraries and frameworks using Context7 API.
 */
export interface ReadDocsParams {
  /** The exact library or framework name (e.g., "Next.js", "MongoDB", "React"). Use the official name as it appears in documentation, not a search query. */
  libraryTitle: string
  /** Optional specific topic to focus on (e.g., "routing", "hooks", "authentication") */
  topic?: string
  /** Optional maximum number of tokens to return. Defaults to 10000. Values less than 10000 are automatically increased to 10000. */
  max_tokens?: number
}

/**
 * Read the multiple files from disk and return their contents. Use this tool to read as many files as would be helpful to answer the user's request.
 */
export interface ReadFilesParams {
  /** List of file paths to read. */
  paths: string[]
}

/**
 * Parameters for run_file_change_hooks tool
 */
export interface RunFileChangeHooksParams {
  /** List of file paths that were changed and should trigger file change hooks */
  files: string[]
}

/**
 * Execute a CLI command from the **project root** (different from the user's cwd).
 */
export interface RunTerminalCommandParams {
  /** CLI command valid for user's OS. */
  command: string
  /** Either SYNC (waits, returns output) or BACKGROUND (runs in background). Default SYNC */
  process_type?: 'SYNC' | 'BACKGROUND'
  /** The working directory to run the command in. Default is the project root. */
  cwd?: string
  /** Set to -1 for no timeout. Does not apply for BACKGROUND commands. Default 30 */
  timeout_seconds?: number
}

/**
 * Set the conversation history to the provided messages.
 */
export interface SetMessagesParams {
  messages: {
    role: 'user' | 'assistant'
    content: string
  }[]
}

/**
 * JSON object to set as the agent output. This completely replaces any previous output. If the agent was spawned, this value will be passed back to its parent. If the agent has an outputSchema defined, the output will be validated against it.
 */
export interface SetOutputParams {}

/**
 * Spawn multiple agents and send a prompt to each of them.
 */
export interface SpawnAgentsParams {
  agents: {
    /** Agent to spawn */
    agent_type: string
    /** Prompt to send to the agent */
    prompt?: string
    /** Parameters object for the agent (if any) */
    params?: Record<string, any>
  }[]
}

/**
 * Replace strings in a file with new strings.
 */
export interface StrReplaceParams {
  /** The path to the file to edit. */
  path: string
  /** Array of replacements to make. */
  replacements: {
    /** The string to replace. This must be an *exact match* of the string you want to replace, including whitespace and punctuation. */
    old: string
    /** The string to replace the corresponding old string with. Can be empty to delete. */
    new: string
  }[]
}

/**
 * Deeply consider complex tasks by brainstorming approaches and tradeoffs step-by-step.
 */
export interface ThinkDeeplyParams {
  /** Detailed step-by-step analysis. Initially keep each step concise (max ~5-7 words per step). */
  thought: string
}

/**
 * Search the web for current information using Linkup API.
 */
export interface WebSearchParams {
  /** The search query to find relevant web content */
  query: string
  /** Search depth - 'standard' for quick results, 'deep' for more comprehensive search. Default is 'standard'. */
  depth: 'standard' | 'deep'
}

/**
 * Create or edit a file with the given content.
 */
export interface WriteFileParams {
  /** Path to the file relative to the **project root** */
  path: string
  /** What the change is intended to do in only one sentence. */
  instructions: string
  /** Edit snippet to apply to the file. */
  content: string
}

/**
 * Get parameters type for a specific tool
 */
export type GetToolParams<T extends ToolName> = ToolParamsMap[T]

import * as fs from 'fs'
import * as path from 'path'

import { AGENT_TEMPLATES_DIR } from '@codebuff/common/old-constants'
import { AgentTemplateTypes } from '@codebuff/common/types/session-state'
import {
  filterCustomAgentFiles,
  extractAgentIdFromFileName,
} from '@codebuff/common/util/agent-file-utils'
import { green, yellow, cyan, magenta, bold, gray, red } from 'picocolors'

import { loadLocalAgents, getLoadedAgentNames } from '../agents/load-agents'
import { CLI } from '../cli'
import { getProjectRoot } from '../project-files'
import { Spinner } from '../utils/spinner'
import {
  ENTER_ALT_BUFFER,
  EXIT_ALT_BUFFER,
  CLEAR_SCREEN,
  HIDE_CURSOR,
  SHOW_CURSOR,
} from '../utils/terminal'

let isInAgentsBuffer = false
let originalKeyHandlers: ((str: string, key: any) => void)[] = []
let selectedIndex = 0
let scrollOffset = 0
let allContentLines: string[] = []
let agentLinePositions: number[] = []
let agentList: Array<{
  id: string
  name: string
  description?: string
  isBuiltIn: boolean
  filePath?: string
  isCreateNew?: boolean
  isEditAgent?: boolean
  isSeparator?: boolean
  isPlaceholder?: boolean
  isSectionHeader?: boolean
}> = []

export function isInAgentsMode(): boolean {
  return isInAgentsBuffer
}

export async function enterAgentsBuffer(rl: any, onExit: () => void) {
  if (isInAgentsBuffer) {
    console.log(yellow('Already in agents mode!'))
    return
  }

  // Load local agents
  await loadLocalAgents({ verbose: false })
  const localAgents = getLoadedAgentNames()

  // Build management actions section with header
  const actions: typeof agentList = [
    {
      id: '__header__',
      name: bold(cyan('Actions')),
      description: '',
      isBuiltIn: false,
      isSectionHeader: true,
    },
    {
      id: '__create_new__',
      name: '+ Create New Agent',
      description: 'Create a new custom agent template',
      isBuiltIn: false,
      isCreateNew: true,
    },
  ]

  // Get custom agent files for display purposes
  const agentsDir = path.join(getProjectRoot(), AGENT_TEMPLATES_DIR)
  let customAgentFiles: string[] = []
  if (fs.existsSync(agentsDir)) {
    const files = fs.readdirSync(agentsDir)
    customAgentFiles = filterCustomAgentFiles(files)
  }

  // Add agents section header
  actions.push({
    id: '__agents_header__',
    name:
      bold(cyan('Custom Agents')) +
      gray(` • ${customAgentFiles.length} in ${AGENT_TEMPLATES_DIR}`),
    description: '',
    isBuiltIn: false,
    isSectionHeader: true,
  })

  // Build agent list starting with management actions
  agentList = [...actions]

  // Add custom agents from .agents/templates
  if (customAgentFiles.length > 0) {
    for (const file of customAgentFiles) {
      const agentId = extractAgentIdFromFileName(file)
      const agentName = localAgents[agentId] || agentId
      agentList.push({
        id: agentId,
        name: agentName,
        description: 'Custom user-defined agent',
        isBuiltIn: false,
        filePath: path.join(agentsDir, file),
      })
    }
  } else {
    // If no custom agents, add a helpful message
    agentList.push({
      id: '__no_agents__',
      name: gray('No custom agents found'),
      description: 'Use "Create New Agent" above to get started',
      isBuiltIn: false,
      isPlaceholder: true,
    })
  }

  // No need for special handling here since we now have a proper placeholder

  // Initialize selection to first selectable item
  selectedIndex = 0
  // Find first selectable item (skip section headers, separators, placeholders)
  while (
    selectedIndex < agentList.length &&
    (agentList[selectedIndex]?.isSectionHeader ||
      agentList[selectedIndex]?.isSeparator ||
      agentList[selectedIndex]?.isPlaceholder)
  ) {
    selectedIndex++
  }
  // If no selectable items found, default to 0
  if (selectedIndex >= agentList.length) {
    selectedIndex = 0
  }
  scrollOffset = 0

  // Enter alternate screen buffer
  process.stdout.write(ENTER_ALT_BUFFER)
  process.stdout.write(CLEAR_SCREEN)
  process.stdout.write(HIDE_CURSOR)

  isInAgentsBuffer = true

  // Build content and render
  buildAllContentLines()
  centerSelectedItem()
  renderAgentsList()

  // Set up key handler
  setupAgentsKeyHandler(rl, onExit)
}

export function exitAgentsBuffer(rl: any) {
  if (!isInAgentsBuffer) {
    return
  }

  // Reset state
  selectedIndex = 0
  scrollOffset = 0
  allContentLines = []
  agentLinePositions = []
  agentList = []

  // Restore all original key handlers
  if (originalKeyHandlers.length > 0) {
    process.stdin.removeAllListeners('keypress')
    originalKeyHandlers.forEach((handler) => {
      process.stdin.on('keypress', handler)
    })
    originalKeyHandlers = []
  }

  // Exit alternate screen buffer
  process.stdout.write(SHOW_CURSOR)
  process.stdout.write(EXIT_ALT_BUFFER)

  isInAgentsBuffer = false
}

function centerSelectedItem() {
  if (selectedIndex < 0 || selectedIndex >= agentLinePositions.length) {
    return
  }

  const terminalHeight = process.stdout.rows || 24
  const terminalWidth = process.stdout.columns || 80
  const headerHeight = getHeaderLines(terminalWidth).length
  const maxScrollableLines = terminalHeight - headerHeight - 2
  const selectedLineIndex = agentLinePositions[selectedIndex]
  const maxScrollOffset = Math.max(
    0,
    allContentLines.length - maxScrollableLines,
  )

  // Center item in the scrollable viewport
  const centerOffset = selectedLineIndex - Math.floor(maxScrollableLines / 2)
  scrollOffset = Math.max(0, Math.min(maxScrollOffset, centerOffset))
}

