  )
  const program = ts.createProgram(fullFilePaths, {})

  for (let i = 0; i < filePaths.length; i++) {
    const filePath = filePaths[i]
    const fullFilePath = fullFilePaths[i]
    const sourceFile = program.getSourceFile(fullFilePath)
    if (sourceFile) {
      try {
        const exportedTokens = getExportedTokens(sourceFile)
        result[filePath] = exportedTokens
      } catch (error) {
        console.error(`Error processing file ${fullFilePath}:`, error)
        result[filePath] = []
      }
    } else {
      // console.error(`Could not find source file: ${fullFilePath}`)
      result[filePath] = []
    }
  }

  return result
}

function getExportedTokens(sourceFile: ts.SourceFile): string[] {
  const exportedTokens: string[] = []

  function visit(node: ts.Node) {
    if (ts.isExportDeclaration(node)) {
      if (node.exportClause && ts.isNamedExports(node.exportClause)) {
        node.exportClause.elements.forEach((element) => {
          exportedTokens.push(element.name.text)
        })
      }
    } else if (
      ts.isFunctionDeclaration(node) ||
      ts.isClassDeclaration(node) ||
      ts.isVariableStatement(node)
    ) {
      if (
        node.modifiers?.some(
          (modifier) => modifier.kind === ts.SyntaxKind.ExportKeyword
        )
      ) {
        if (ts.isFunctionDeclaration(node) || ts.isClassDeclaration(node)) {
          if (node.name) {
            exportedTokens.push(node.name.text)
          }
        } else if (ts.isVariableStatement(node)) {
          node.declarationList.declarations.forEach((declaration) => {
            if (ts.isIdentifier(declaration.name)) {
              exportedTokens.push(declaration.name.text)
            }
          })
        }
      }
    }

    ts.forEachChild(node, visit)
  }

  visit(sourceFile)

  return exportedTokens
}
*/

export const deleteFile = (fullPath: string): boolean => {
  try {
    if (fs.existsSync(fullPath)) {
      fs.unlinkSync(fullPath)
      return true
    }
    return false
  } catch (error) {
    console.error(`Error deleting file ${fullPath}:`, error)
    logger.error(
      {
        errorMessage: error instanceof Error ? error.message : String(error),
        errorStack: error instanceof Error ? error.stack : undefined,
        fullPath,
      },
      'Error deleting file',
    )
    return false
  }
}

import { red, yellow } from 'picocolors'

import { websiteUrl } from '../config'
import { logger } from './logger'

import type { User } from '@codebuff/common/util/credentials'

/**
 * Validates agent configs using the REST API if user is authenticated
 * @param user The user object (null if not authenticated)
 * @param agentConfigs The agent configs to validate
 */
export async function validateAgentConfigsIfAuthenticated(
  user: User | undefined,
  agentConfigs: Record<string, any> | undefined,
): Promise<void> {
  // Only validate if user is authenticated and there are agent configs
  const agentConfigKeys = Object.keys(agentConfigs || {})

  if (!user || !agentConfigs || agentConfigKeys.length === 0) {
    return
  }

  try {
    const response = await fetch(`${websiteUrl}/api/agents/validate`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Cookie: `next-auth.session-token=${user.authToken}`,
      },
      body: JSON.stringify({ agentConfigs }),
    })

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}))
      const errorMessage =
        (errorData as any).error ||
        `HTTP ${response.status}: ${response.statusText}`
      console.log(`\n${red('Agent Config Validation Error:')} ${errorMessage}`)
      return
    }

    const data = await response.json()

    if (data.validationErrors && data.validationErrors.length > 0) {
      const errorMessage = data.validationErrors
        .map((err: { filePath: string; message: string }) => err.message)
        .join('\n')
      console.log(
        `\n${yellow('Agent Config Validation Warnings:')}\n${errorMessage}`,
      )
    }
  } catch (error) {
    logger.warn(
      {
        errorMessage: error instanceof Error ? error.message : String(error),
        errorStack: error instanceof Error ? error.stack : undefined,
      },
      'Failed to validate agent configs via REST API',
    )
  }
}

import { validateAgents } from '@codebuff/common/templates/agent-validation'
import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'

import { authOptions } from '@/app/api/auth/[...nextauth]/auth-options'
import { logger } from '@/util/logger'

import type { NextRequest } from 'next/server'

interface ValidateAgentsRequest {
  agentConfigs: Record<string, any>
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = (await request.json()) as ValidateAgentsRequest
    const { agentConfigs } = body

    if (!agentConfigs || typeof agentConfigs !== 'object') {
      return NextResponse.json(
        {
          error:
            'Invalid request: agentConfigs must be an object, with keys being the agent IDs and values of type AgentConfig',
        },
        { status: 400 }
      )
    }

    const { templates: configs, validationErrors } = validateAgents(agentConfigs)

    if (validationErrors.length > 0) {
      logger.warn(
        { errorCount: validationErrors.length, userId: session.user.id },
        'Agent config validation errors found',
      )
    }

    return NextResponse.json({
      success: true,
      configs: Object.keys(configs),
      validationErrors,
      errorCount: validationErrors.length,
    })
  } catch (error) {
    logger.error(
      { error: error instanceof Error ? error.message : String(error) },
      'Error validating agent configs',
    )
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 },
    )
  }
}

