    expect(websocketAction.requestFiles).toHaveBeenCalledWith(
      expect.any(Object), // WebSocket
      ['src/test.ts'],
    )
  })

  it('should spawn agent inline that deletes last two assistant messages', async () => {
    // Create a mock inline agent template that deletes messages
    const mockInlineAgentTemplate: AgentTemplate = {
      id: 'message-deleter-agent',
      displayName: 'Message Deleter Agent',
      parentPrompt: 'Deletes assistant messages',
      model: 'claude-3-5-sonnet-20241022',
      inputSchema: {},
      outputMode: 'json' as const,
      includeMessageHistory: true,
      toolNames: ['set_messages', 'end_turn'],
      subagents: [],
      systemPrompt: 'Delete messages system prompt',
      instructionsPrompt: 'Delete messages instructions prompt',
      stepPrompt: 'Delete messages step prompt',
      handleSteps: function* ({ agentState, prompt, params }) {
        // Delete the last two assistant messages by doing two iterations
        const messages = [...agentState.messageHistory]

        // First iteration: find and remove the last assistant message
        for (let i = messages.length - 1; i >= 0; i--) {
          if (messages[i].role === 'assistant') {
            messages.splice(i, 1)
            break
          }
        }

        // Second iteration: find and remove the next-to-last assistant message
        for (let i = messages.length - 1; i >= 0; i--) {
          if (messages[i].role === 'assistant') {
            messages.splice(i, 1)
            break
          }
        }

        // Set the updated messages
        yield {
          toolName: 'set_messages',
          args: { messages },
        }
      },
    }

    // Create a parent agent template that can spawn the inline agent
    const mockParentAgentTemplate: AgentTemplate = {
      id: 'parent-agent',
      displayName: 'Parent Agent',
      parentPrompt: 'Parent agent that spawns inline agents',
      model: 'claude-3-5-sonnet-20241022',
      inputSchema: {},
      outputMode: 'json' as const,
      includeMessageHistory: true,
      toolNames: ['spawn_agent_inline', 'end_turn'],
      subagents: ['message-deleter-agent'],
      systemPrompt: 'Parent system prompt',
      instructionsPrompt: 'Parent instructions prompt',
      stepPrompt: 'Parent step prompt',
    }

    // Mock the agent registry to include both agents
    const mockAgentRegistry = {
      'parent-agent': mockParentAgentTemplate,
      'message-deleter-agent': mockInlineAgentTemplate,
    }

    // Mock the LLM stream to spawn the inline agent
    spyOn(aisdk, 'promptAiSdkStream').mockImplementation(async function* () {
      yield getToolCallString('spawn_agent_inline', {
        agent_type: 'message-deleter-agent',
        prompt: 'Delete the last two assistant messages',
      })
    })

    const sessionState = getInitialSessionState(mockFileContext)
    const agentState = sessionState.mainAgentState

    // Add some initial messages including assistant messages to delete
    agentState.messageHistory = [
      { role: 'user', content: 'Hello' },
      { role: 'assistant', content: 'Hi there!' },
      { role: 'user', content: 'How are you?' },
      { role: 'assistant', content: 'I am doing well, thank you!' },
      { role: 'user', content: 'Can you help me?' },
      { role: 'assistant', content: 'Of course, I would be happy to help!' },
    ]

    const result = await runAgentStep(
      new MockWebSocket() as unknown as WebSocket,
      {
        userId: TEST_USER_ID,
        userInputId: 'test-input',
        clientSessionId: 'test-session',
        fingerprintId: 'test-fingerprint',
        onResponseChunk: () => {},
        agentType: 'parent-agent' as any,
        fileContext: mockFileContext,
        localAgentTemplates: mockAgentRegistry,
        agentState,
        prompt: 'Spawn an inline agent to clean up messages',
        params: undefined,
      },
    )

    const finalMessages = result.agentState.messageHistory

    // This integration test demonstrates that spawn_agent_inline tool calls are executed successfully!
    // The inline agent runs its handleSteps function and executes tool calls

    // Verify the exact sequence of messages in the final message history
    // The inline agent's instructionsPrompt and stepPrompt should be removed by expireMessages
    const expectedMessages = [
      { role: 'user', content: 'Hello' },
      { role: 'assistant', content: 'Hi there!' },
      { role: 'user', content: 'How are you?' },
      { role: 'assistant', content: 'I am doing well, thank you!' },
      { role: 'user', content: 'Can you help me?' },
      {
        role: 'user',
        content: expect.stringContaining(
          'Spawn an inline agent to clean up messages',
        ),
      },
      {
        role: 'user',
        content: expect.stringContaining(
          'Delete the last two assistant messages',
        ),
      },
    ]

    expectedMessages.forEach((expected, index) => {
      expect(finalMessages[index]).toMatchObject(expected)
    })
    expect(finalMessages).toHaveLength(expectedMessages.length)
  })
})

import { generateCompactId } from '@codebuff/common/util/string'

import { getAgentTemplate } from '../../../templates/agent-registry'
import { logger } from '../../../util/logger'
import { expireMessages } from '../../../util/messages'

import type { AgentTemplate } from '@codebuff/common/types/agent-template'
import type { CodebuffToolCall } from '../../constants'
import type { CodebuffToolHandlerFunction } from '../handler-function-type'
import type { CodebuffMessage } from '@codebuff/common/types/message'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type {
  AgentState,
  AgentTemplateType,
} from '@codebuff/common/types/session-state'
import type { ProjectFileContext } from '@codebuff/common/util/file'
import type { WebSocket } from 'ws'

export const handleSpawnAgentInline = ((params: {

  previousToolCallFinished: Promise<void>
  toolCall: CodebuffToolCall<'spawn_agent_inline'>
  fileContext: ProjectFileContext
  clientSessionId: string
  userInputId: string

  getLatestState: () => { messages: CodebuffMessage[] }
  state: {
    ws?: WebSocket
    fingerprintId?: string
    userId?: string
    agentTemplate?: AgentTemplate
    localAgentTemplates?: Record<string, AgentTemplate>
    messages?: CodebuffMessage[]
    agentState?: AgentState
  }
}): { result: Promise<undefined>; state: {} } => {
  const {
    previousToolCallFinished,
    toolCall,
    fileContext,
    clientSessionId,
    userInputId,
    getLatestState,
    state,
  } = params
  const {
    agent_type: agentTypeStr,
    prompt,
    params: agentParams,
  } = toolCall.args
  const {
    ws,
    fingerprintId,
    userId,
    agentTemplate: parentAgentTemplate,
    localAgentTemplates,
    messages,
  } = state
  let { agentState } = state

  if (!ws) {
    throw new Error(
      'Internal error for spawn_agent_inline: Missing WebSocket in state',
    )
  }
  if (!fingerprintId) {
    throw new Error(
      'Internal error for spawn_agent_inline: Missing fingerprintId in state',
    )
  }
  if (!parentAgentTemplate) {
    throw new Error(
      'Internal error for spawn_agent_inline: Missing agentTemplate in state',
    )
  }
  if (!messages) {
    throw new Error(
      'Internal error for spawn_agent_inline: Missing messages in state',
    )
  }
  if (!agentState) {
    throw new Error(
      'Internal error for spawn_agent_inline: Missing agentState in state',
    )
  }
  if (!localAgentTemplates) {
    throw new Error(
      'Internal error for spawn_agent_inline: Missing localAgentTemplates in state',
    )
  }

  const triggerSpawnAgentInline = async () => {
    const agentType = agentTypeStr as AgentTemplateType
    const agentTemplate = await getAgentTemplate(agentType, localAgentTemplates)

    if (!agentTemplate) {
      throw new Error(`Agent type ${agentTypeStr} not found.`)
    }

    if (!parentAgentTemplate.subagents.includes(agentType)) {
      throw new Error(
        `Agent type ${parentAgentTemplate.id} is not allowed to spawn child agent type ${agentType}.`,
      )
    }

    // Validate prompt and params against agent's schema
    const { inputSchema } = agentTemplate

    // Validate prompt requirement
    if (inputSchema.prompt) {
      const result = inputSchema.prompt.safeParse(prompt)
      if (!result.success) {
        throw new Error(
          `Invalid prompt for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`,
        )
      }
    }

    // Validate params if schema exists
    if (inputSchema.params) {
      const result = inputSchema.params.safeParse(agentParams)
      if (!result.success) {
        throw new Error(
          `Invalid params for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`,
        )
      }
    }

    const agentId = generateCompactId()

    // Create child agent state that shares message history with parent
    const childAgentState: AgentState = {
      agentId,
      agentType,
      agentContext: agentState!.agentContext, // Inherit parent context directly
      subagents: [],
      messageHistory: getLatestState().messages, // Share the same message array
      stepsRemaining: 20, // MAX_AGENT_STEPS
      output: undefined,
      parentId: agentState!.agentId,
    }

    logger.debug(
      {
        agentTemplate,
        prompt,
        params: agentParams,
        agentId,
        parentId: childAgentState.parentId,
      },
      `Spawning agent inline — ${agentType} (${agentId})`,
    )

    // Import loopAgentSteps dynamically to avoid circular dependency
    const { loopAgentSteps } = await import('../../../run-agent-step')

    const result = await loopAgentSteps(ws, {
      userInputId: `${userInputId}-inline-${agentType}${agentId}`,
      prompt: prompt || '',
      params: agentParams,
      agentType: agentTemplate.id,
      agentState: childAgentState,
      fingerprintId,
      fileContext,
      localAgentTemplates,
      toolResults: [],
      userId,
      clientSessionId,
      onResponseChunk: (chunk: string | PrintModeEvent) => {
        // Child agent output is streamed directly to parent's output
        // No need for special handling since we share message history
      },
    })

    // Update parent's message history with child's final state
    // Since we share the same message array reference, this should already be updated
    let finalMessages = result.agentState?.messageHistory || state.messages

    // Expire messages with timeToLive: 'userPrompt' to clean up inline agent's temporary messages
    finalMessages = expireMessages(finalMessages, 'userPrompt')

    state.messages = finalMessages

    // Update parent agent state to reflect shared message history
    if (agentState && result.agentState) {
      agentState.messageHistory = finalMessages
    }

    return undefined
  }

  return {
    result: previousToolCallFinished.then(triggerSpawnAgentInline),
    state: {},
  }
}) satisfies CodebuffToolHandlerFunction<'spawn_agent_inline'>

