    { resolve: (response: any) => void; reject: (error: any) => void }
  > = {}

  constructor({ apiKey, cwd, onError, overrideTools }: CodebuffClientOptions) {
    // TODO: download binary automatically
    const isWindows = process.platform === 'win32'
    if (
      execFileSync(isWindows ? 'where' : 'which', [CODEBUFF_BINARY])
        .toString()
        .trim() === ''
    ) {
      throw new Error(
        `Could not find ${CODEBUFF_BINARY} in PATH. Please run "npm i -g codebuff" to install codebuff.`,
      )
    }
    const foundApiKey = apiKey ?? process.env[API_KEY_ENV_VAR]
    if (!foundApiKey) {
      throw new Error(
        `Codebuff API key not found. Please provide an apiKey in the constructor of CodebuffClient or set the ${API_KEY_ENV_VAR} environment variable.`,
      )
    }

    this.cwd = cwd
    this.overrideTools = overrideTools ?? {}
    this.websocketHandler = new WebSocketHandler({
      apiKey: foundApiKey,
      onWebsocketError: (error) => {
        onError({ message: error.message })
      },
      onWebsocketReconnect: () => {},
      onRequestReconnect: async () => {},
      onResponseError: async (error) => {
        onError({ message: error.message })
      },
      readFiles: this.readFiles.bind(this),
      handleToolCall: this.handleToolCall.bind(this),
      onCostResponse: async () => {},

      onResponseChunk: async (action) => {
        const { userInputId, chunk } = action
        const handleEvent = this.promptIdToHandleEvent[userInputId]
        if (handleEvent && typeof chunk === 'object') {
          handleEvent(chunk)
        }
      },
      onSubagentResponseChunk: async () => {},

      onPromptResponse: this.handlePromptResponse.bind(this),
    })
  }

  /**
   * Run a Codebuff agent with the specified options.
   *
   * @param agent - The agent to run. Use 'base' for the default agent, or specify a custom agent ID if you made your own agent config.
   * @param prompt - The user prompt describing what you want the agent to do.
   * @param params - (Optional) Additional parameters for the agent. Most agents don't use this, but some custom agents can take a JSON object as input in addition to the user prompt string.
   * @param handleEvent - (Optional) Callback function that receives every event during execution (assistant messages, tool calls, etc.). This allows you to stream the agent's progress in real-time. We will likely add a token-by-token streaming callback in the future.
   * @param previousRun - (Optional) JSON state returned from a previous run() call. Use this to continue a conversation or session with the agent, maintaining context from previous interactions.
   * @param projectFiles - (Optional) All the files in your project as a plain JavaScript object. Keys should be the full path from your current directory to each file, and values should be the string contents of the file. Example: { "src/index.ts": "console.log('hi')" }. This helps Codebuff pick good source files for context.
   * @param knowledgeFiles - (Optional) Knowledge files to inject into every run() call. Uses the same schema as projectFiles - keys are file paths and values are file contents. These files are added directly to the agent's context.
   * @param agentConfigs - (Optional) Array of custom agent configurations. Each object should satisfy the AgentConfig type.
   * @param maxAgentSteps - (Optional) Maximum number of steps the agent can take before stopping. Use this as a safety measure in case your agent starts going off the rails. A reasonable number is around 20.
   *
   * @returns A Promise that resolves to a RunState JSON object which you can pass to a subsequent run() call to continue the run.
   */
  public async run({
    agent,
    prompt,
    params,
    handleEvent,
    previousRun,
    projectFiles,
    knowledgeFiles,
    agentConfigs,
    maxAgentSteps,
  }: {
    agent: string
    prompt: string
    params?: Record<string, any>
    handleEvent?: (event: PrintModeEvent) => void
    previousRun?: RunState
    projectFiles?: Record<string, string>
    knowledgeFiles?: Record<string, string>
    agentConfigs?: AgentConfig[]
    maxAgentSteps?: number
  }): Promise<RunState> {
    await this.websocketHandler.connect()

    const promptId = Math.random().toString(36).substring(2, 15)
    const sessionState =
      previousRun?.sessionState ??
      initialSessionState(this.cwd, {
        knowledgeFiles,
        agentConfigs,
        projectFiles,
        maxAgentSteps,
      })
    const toolResults = previousRun?.toolResults ?? []
    if (handleEvent) {
      this.promptIdToHandleEvent[promptId] = handleEvent
    }
    this.websocketHandler.sendInput({
      promptId,
      prompt,
      promptParams: params,
      fingerprintId: this.fingerprintId,
      costMode: 'normal',
      sessionState,
      toolResults,
      agentId: agent,
    })

    return new Promise<RunState>((resolve, reject) => {
      this.promptIdToResolveResponse[promptId] = { resolve, reject }
    })
  }

  private async handlePromptResponse(
    action: Extract<ServerAction, { type: 'prompt-response' }>,
  ) {
    const promiseActions =
      this.promptIdToResolveResponse[action?.promptId ?? '']

    const parsedAction = PromptResponseSchema.safeParse(action)
    if (!parsedAction.success) {
      const message = [
        'Received invalid prompt response from server:',
        JSON.stringify(parsedAction.error.errors),
        'If this issues persists, please contact support@codebuff.com',
      ].join('\n')
      if (promiseActions) {
        promiseActions.reject(new Error(message))
      }
      return
    }

    if (promiseActions) {
      const { sessionState, toolResults } = parsedAction.data
      const state: RunState = {
        sessionState,
        toolResults,
      }
      promiseActions.resolve(state)

      delete this.promptIdToResolveResponse[action.promptId]
      delete this.promptIdToHandleEvent[action.promptId]
    }
  }

  private async readFiles(filePath: string[]) {
    const override = this.overrideTools.read_files
    if (override) {
      const overrideResult = await override(filePath)
      return overrideResult.files
    }
    return getFiles(filePath, this.cwd)
  }

  private async handleToolCall(
    action: Extract<ServerAction, { type: 'tool-call-request' }>,
  ) {
    const toolName = action.toolName
    const args = action.args
    let result: string
    try {
      let override = this.overrideTools[toolName as ClientToolName]
      if (!override && toolName === 'str_replace') {
        // Note: write_file and str_replace have the same implementation, so reuse their write_file override.
        override = this.overrideTools['write_file']
      }
      if (override) {
        const overrideResult = await override(args)
        result = overrideResult.toolResultMessage
      } else if (toolName === 'end_turn') {
        result = ''
      } else if (toolName === 'write_file' || toolName === 'str_replace') {
        const r = changeFile(args, this.cwd)
        result = r.toolResultMessage
      } else if (toolName === 'run_terminal_command') {
        throw new Error(
          'run_terminal_command not implemented in SDK yet; please provide an override.',
        )
      } else {
        throw new Error(
          `Tool not implemented in SDK. Please provide an override or modify your agent to not use this tool: ${toolName}`,
        )
      }
    } catch (error) {
      return {
        type: 'tool-call-response',
        requestId: action.requestId,
        success: false,
        result:
          error && typeof error === 'object' && 'message' in error
            ? error.message
            : typeof error === 'string'
              ? error
              : 'Unknown error',
      }
    }
    return {
      type: 'tool-call-response',
      requestId: action.requestId,
      success: true,
      result,
    }
  }
}

function initialSessionState(
  cwd: string,
  options: {
    // TODO: Parse projectFiles into fileTree, fileTokenScores, tokenCallers
    projectFiles?: Record<string, string>
    knowledgeFiles?: Record<string, string>
    agentConfigs?: AgentConfig[]
    maxAgentSteps?: number
  },
) {
  const { knowledgeFiles = {}, agentConfigs = [] } = options

  // Process agentConfigs array and convert handleSteps functions to strings
  const processedAgentTemplates: Record<string, any> = {}
  agentConfigs.forEach((config) => {
    const processedConfig = { ...config } as Record<string, any>
    if (
      processedConfig.handleSteps &&
      typeof processedConfig.handleSteps === 'function'
    ) {
      processedConfig.handleSteps = processedConfig.handleSteps.toString()
    }
    if (processedConfig.id) {
      processedAgentTemplates[processedConfig.id] = processedConfig
    }
  })

  const initialState = getInitialSessionState({
    projectRoot: cwd,
    cwd,
    fileTree: [],
    fileTokenScores: {},
    tokenCallers: {},
    knowledgeFiles,
    userKnowledgeFiles: {},
    agentTemplates: processedAgentTemplates,
    gitChanges: {
      status: '',
      diff: '',
      diffCached: '',
      lastCommitMessages: '',
    },
    changesSinceLastChat: {},
    shellConfigFiles: {},
    systemInfo: {
      platform: process.platform,
      shell: process.platform === 'win32' ? 'cmd.exe' : 'bash',
      nodeVersion: process.version,
      arch: process.arch,
      homedir: os.homedir(),
      cpus: os.cpus().length ?? 1,
    },
  })

  if (options.maxAgentSteps) {
    initialState.mainAgentState.stepsRemaining = options.maxAgentSteps
  }

  return initialState
}

/**
 * Codebuff Agent Type Definitions
 *
 * This file provides TypeScript type definitions for creating custom Codebuff agents.
 * Import these types in your agent files to get full type safety and IntelliSense.
 *
 * Usage in .agents/your-agent.ts:
 *   import { AgentConfig, ToolName, ModelName } from './types/agent-config'
 *
 *   const config: AgentConfig = {
 *     // ... your agent configuration with full type safety ...
 *   }
 *
 *   export default config
 */

// ============================================================================
// Core Agent Configuration Types
// ============================================================================

export interface AgentConfig {
  /** Unique identifier for this agent. Must contain only lowercase letters, numbers, and hyphens, e.g. 'code-reviewer' */
  id: string

  /** Version string (if not provided, will default to '0.0.1' and be bumped on each publish) */
  version?: string

  /** Publisher ID for the agent. Must be provided if you want to publish the agent. */
  publisher?: string

  /** Human-readable name for the agent */
  displayName: string

  /** AI model to use for this agent. Can be any model in OpenRouter: https://openrouter.ai/models */
  model: ModelName

  // ============================================================================
  // Tools and Subagents
  // ============================================================================

  /** Tools this agent can use. */
  toolNames?: ToolName[]

  /** Other agents this agent can spawn. */
  subagents?: SubagentName[]

  // ============================================================================
  // Input and Output
  // ============================================================================

  /** The input schema required to spawn the agent. Provide a prompt string and/or a params object or none.
   * 80% of the time you want just a prompt string with a description:
   * inputSchema: {
   *   prompt: { type: 'string', description: 'A description of what info would be helpful to the agent' }
   * }
   */
  inputSchema?: {
    prompt?: { type: 'string'; description?: string }
    params?: JsonSchema
  }

  /** Whether to include conversation history from the parent agent in context.
   *
   * Defaults to false.
   * Use this if the agent needs to know all the previous messages in the conversation.
   */
  includeMessageHistory?: boolean

  /** How the agent should output a response to its parent (defaults to 'last_message')
   *
   * last_message: The last message from the agent, typcically after using tools.
   *
   * all_messages: All messages from the agent, including tool calls and results.
   *
   * json: Make the agent output a JSON object. Can be used with outputSchema or without if you want freeform json output.
   */
  outputMode?: 'last_message' | 'all_messages' | 'json'

  /** JSON schema for structured output (when outputMode is 'json') */
  outputSchema?: JsonSchema

  // ============================================================================
  // Prompts
  // ============================================================================

  /** Prompt for when to spawn this agent as a subagent. Include the main purpose and use cases.
   *
   * This field is key if the agent is a subagent and intended to be spawned. */
  parentPrompt?: string

  /** Background information for the agent. Fairly optional. Prefer using instructionsPrompt for agent instructions. */
  systemPrompt?: string

  /** Instructions for the agent.
   *
   * IMPORTANT: Updating this prompt is the best way to shape the agent's behavior.
   * This prompt is inserted after each user input. */
  instructionsPrompt?: string

  /** Prompt inserted at each agent step.
   *
   * Powerful for changing the agent's behavior, but usually not necessary for smart models.
   * Prefer instructionsPrompt for most instructions. */
  stepPrompt?: string

  // ============================================================================
  // Handle Steps
  // ============================================================================

  /** Programmatically step the agent forward and run tools.
   *
   * You can either yield:
   * - A tool call object with toolName and args properties.
   * - 'STEP' to run agent's model and generate one assistant message.
   * - 'STEP_ALL' to run the agent's model until it uses the end_turn tool or stops includes no tool calls in a message.
   *
   * Or use 'return' to end the turn.
   *
   * Example 1:
   * function* handleSteps({ agentStep, prompt, params}) {
   *   const { toolResult } = yield {
   *     toolName: 'read_files',
   *     args: { paths: ['file1.txt', 'file2.txt'] }
   *   }
   *   yield 'STEP_ALL'
   * }
   *
   * Example 2:
   * handleSteps: function* ({ agentState, prompt, params }) {
   *   while (true) {
   *     yield {
   *       toolName: 'spawn_agents',
   *       args: {
   *         agents: [
   *         {
   *           agent_type: 'thinker',
   *           prompt: 'Think deeply about the user request',
   *         },
   *       ],
   *     },
   *   }
   *   yield 'STEP'
   * }
   * }
   */
  handleSteps?: (
    context: AgentStepContext,
  ) => Generator<
    ToolCall | 'STEP' | 'STEP_ALL',
    void,
    { agentState: AgentState; toolResult: ToolResult | undefined }
  >
}

// ============================================================================
// Supporting Types
// ============================================================================

export interface AgentState {
  agentId: string
  parentId: string
  messageHistory: Message[]
}

/**
 * Message in conversation history
 */
export interface Message {
  role: 'user' | 'assistant' | 'system'
  content: string
  timestamp?: number
}

/**
 * Context provided to handleSteps generator function
 */
export interface AgentStepContext {
  agentState: AgentState
  prompt?: string
  params?: Record<string, any>
}

/**
 * Tool call object for handleSteps generator
 */
export type ToolCall<T extends ToolName = ToolName> = {
  [K in T]: {
    toolName: K
    args?: Tools.GetToolParams<K>
  }
}[T]

/**
 * Result from executing a tool
 */
export interface ToolResult {
  toolName: string
  toolCallId: string
  result: string
}

/**
 * JSON Schema definition (for prompt schema or output schema)
 */
export interface JsonSchema {
  type: string
  properties?: Record<string, any>
  required?: string[]
  [key: string]: any
}

// ============================================================================
// Available Tools
// ============================================================================

/**
 * File operation tools
 */
export type FileTools =
  | 'read_files'
  | 'write_file'
  | 'str_replace'
  | 'find_files'

/**
 * Code analysis tools
 */
export type CodeAnalysisTools = 'code_search' | 'find_files'

/**
 * Terminal and system tools
 */
export type TerminalTools = 'run_terminal_command' | 'run_file_change_hooks'

/**
 * Web and browser tools
 */
export type WebTools = 'browser_logs' | 'web_search' | 'read_docs'

/**
 * Agent management tools
 */
export type AgentTools =
  | 'spawn_agents'
  | 'spawn_agents_async'
  | 'send_agent_message'
  | 'set_messages'
  | 'add_message'

/**
 * Planning and organization tools
 */
export type PlanningTools =
  | 'think_deeply'
  | 'create_plan'
  | 'add_subgoal'
  | 'update_subgoal'

/**
 * Output and control tools
 */
export type OutputTools = 'set_output' | 'end_turn'

/**
 * Common tool combinations for convenience
 */
export type FileEditingTools = FileTools | 'end_turn'
export type ResearchTools = WebTools | 'write_file' | 'end_turn'
export type CodeAnalysisToolSet = FileTools | CodeAnalysisTools | 'end_turn'

// ============================================================================
// Available Models (see: https://openrouter.ai/models)
// ============================================================================

/**
 * AI models available for agents (all models in OpenRouter are supported)
 *
 * See available models at https://openrouter.ai/models
 */
export type ModelName =
  // Verified OpenRouter Models
  | 'anthropic/claude-4-sonnet-20250522'
  | 'anthropic/claude-opus-4.1'
  | 'anthropic/claude-3.5-haiku-20241022'
  | 'anthropic/claude-3.5-sonnet-20240620'
  | 'openai/gpt-4o-2024-11-20'
  | 'openai/gpt-4o-mini-2024-07-18'
  | 'openai/o3'
  | 'openai/o4-mini'
  | 'openai/o4-mini-high'
  | 'google/gemini-2.5-pro'
  | 'google/gemini-2.5-flash'
  | 'x-ai/grok-4-07-09'
  | (string & {})

// ============================================================================
// Spawnable Agents
// ============================================================================

/**
 * Built-in agents that can be spawned by custom agents
 */
export type SubagentName =
  | 'file-picker'
  | 'file-explorer'
  | 'researcher'
  | 'thinker'
  | 'reviewer'
  | (string & {})

import type * as Tools from './tools'
export type { Tools }
type ToolName = Tools.ToolName

/**
 * Union type of all available tool names
 */
export type ToolName = 'add_message' | 'add_subgoal' | 'browser_logs' | 'code_search' | 'create_plan' | 'end_turn' | 'find_files' | 'read_docs' | 'read_files' | 'run_file_change_hooks' | 'run_terminal_command' | 'send_agent_message' | 'set_messages' | 'set_output' | 'spawn_agents' | 'spawn_agents_async' | 'str_replace' | 'think_deeply' | 'update_subgoal' | 'web_search' | 'write_file'

/**
 * Map of tool names to their parameter types
 */
export interface ToolParamsMap {
  'add_message': AddMessageParams
  'add_subgoal': AddSubgoalParams
  'browser_logs': BrowserLogsParams
  'code_search': CodeSearchParams
  'create_plan': CreatePlanParams
  'end_turn': EndTurnParams
  'find_files': FindFilesParams
  'read_docs': ReadDocsParams
  'read_files': ReadFilesParams
  'run_file_change_hooks': RunFileChangeHooksParams
  'run_terminal_command': RunTerminalCommandParams
  'send_agent_message': SendAgentMessageParams
  'set_messages': SetMessagesParams
  'set_output': SetOutputParams
  'spawn_agents': SpawnAgentsParams
  'spawn_agents_async': SpawnAgentsAsyncParams
  'str_replace': StrReplaceParams
  'think_deeply': ThinkDeeplyParams
  'update_subgoal': UpdateSubgoalParams
  'web_search': WebSearchParams
  'write_file': WriteFileParams
}

/**
 * Add a new message to the conversation history. To be used for complex requests that can't be solved in a single step, as you may forget what happened!
 */
export interface AddMessageParams {
  "role": "user" | "assistant"
  "content": string
}

/**
 * Add a new subgoal for tracking progress. To be used for complex requests that can't be solved in a single step, as you may forget what happened!
 */
export interface AddSubgoalParams {
  // A unique identifier for the subgoal. Try to choose the next sequential integer that is not already in use.
  "id": string
  // The objective of the subgoal, concisely and clearly stated.
  "objective": string
  // The status of the subgoal.
  "status": "NOT_STARTED" | "IN_PROGRESS" | "COMPLETE" | "ABORTED"
  // A plan for the subgoal.
  "plan"?: string
  // A log message for the subgoal progress.
  "log"?: string
}

/**
 * Parameters for browser_logs tool
 */
export interface BrowserLogsParams {
  // The type of browser action to perform (e.g., "navigate").
  "type": string
  // The URL to navigate to.
  "url": string
  // When to consider navigation successful. Defaults to 'load'.
  "waitUntil"?: "load" | "domcontentloaded" | "networkidle0"
}

/**
 * Search for string patterns in the project's files. This tool uses ripgrep (rg), a fast line-oriented search tool. Use this tool only when read_files is not sufficient to find the files you need.
 */
export interface CodeSearchParams {
  // The pattern to search for.
  "pattern": string
  // Optional ripgrep flags to customize the search (e.g., "-i" for case-insensitive, "-t ts" for TypeScript files only, "-A 3" for 3 lines after match, "-B 2" for 2 lines before match, "--type-not test" to exclude test files).
  "flags"?: string
  // Optional working directory to search within, relative to the project root. Defaults to searching the entire project.
  "cwd"?: string
}

/**
 * Generate a detailed markdown plan for complex tasks.
 */
export interface CreatePlanParams {
  // The path including the filename of a markdown file that will be overwritten with the plan.
  "path": string
  // A detailed plan to solve the user's request.
  "plan": string
}

/**
 * End your turn, regardless of any new tool results that might be coming. This will allow the user to type another prompt.
 */
export interface EndTurnParams {

}

/**
 * Find several files related to a brief natural language description of the files or the name of a function or class you are looking for.
 */
export interface FindFilesParams {
  // A brief natural language description of the files or the name of a function or class you are looking for. It's also helpful to mention a directory or two to look within.
  "prompt": string
}

/**
 * Fetch up-to-date documentation for libraries and frameworks using Context7 API.
 */
export interface ReadDocsParams {
  // The exact library or framework name (e.g., "Next.js", "MongoDB", "React"). Use the official name as it appears in documentation, not a search query.
  "libraryTitle": string
  // Optional specific topic to focus on (e.g., "routing", "hooks", "authentication")
  "topic"?: string
  // Optional maximum number of tokens to return. Defaults to 10000. Values less than 10000 are automatically increased to 10000.
  "max_tokens"?: number
}

/**
 * Read the multiple files from disk and return their contents. Use this tool to read as many files as would be helpful to answer the user's request.
 */
export interface ReadFilesParams {
  // List of file paths to read.
  "paths": string[]
}

/**
 * Parameters for run_file_change_hooks tool
 */
export interface RunFileChangeHooksParams {
  // List of file paths that were changed and should trigger file change hooks
  "files": string[]
}

/**
 * Execute a CLI command from the **project root** (different from the user's cwd).
 */
export interface RunTerminalCommandParams {
  // CLI command valid for user's OS.
  "command": string
  // Either SYNC (waits, returns output) or BACKGROUND (runs in background). Default SYNC
  "process_type": "SYNC" | "BACKGROUND"
  // The working directory to run the command in. Default is the project root.
  "cwd"?: string
  // Set to -1 for no timeout. Does not apply for BACKGROUND commands. Default 30
  "timeout_seconds": number
}

/**
 * Send a message to another agent (parent or child) for communication and data exchange.
 */
export interface SendAgentMessageParams {
  // ID of the target agent to send message to. Use "PARENT_ID" to send to parent agent.
  "target_agent_id": string
  // Message prompt to send to the target agent
  "prompt": string
  // Optional parameters object to send with the message
  "params"?: Record<string, any>
}

/**
 * Set the conversation history to the provided messages.
 */
export interface SetMessagesParams {
  "messages": {
  "role": "user" | "assistant"
  "content": string
}[]
}

/**
 * JSON object to set as the agent output. This completely replaces any previous output. If the agent was spawned, this value will be passed back to its parent. If the agent has an outputSchema defined, the output will be validated against it.
 */
export interface SetOutputParams {

}

/**
 * Spawn multiple agents and send a prompt to each of them.
 */
export interface SpawnAgentsParams {
  "agents": {
  // Agent to spawn
  "agent_type": string
  // Prompt to send to the agent
  "prompt"?: string
  // Parameters object for the agent (if any)
  "params"?: Record<string, any>
}[]
}

/**
 * Parameters for spawn_agents_async tool
 */
export interface SpawnAgentsAsyncParams {
  "agents": {
  // Agent to spawn
