    describe('Edge Cases', () => {
      it('should handle git-committer agent schema correctly', async () => {
        const fileContext: ProjectFileContext = {
          ...mockFileContext,
          agentTemplates: {
            'git-committer.ts': {
              id: 'CodebuffAI/git-committer',
