            parentPrompt: 'Invalid agent',
            model: 'anthropic/claude-4-sonnet-20250522',
            systemPrompt: 'Test',
            instructionsPrompt: 'Test',
            stepPrompt: 'Test',
            subagents: ['nonexistent_agent'],
