              model: 'anthropic/claude-4-sonnet-20250522',
              systemPrompt: 'Test system prompt',
              instructionsPrompt: 'Test user prompt',
              stepPrompt: 'Test step prompt',
              outputMode: 'last_message',
              includeMessageHistory: true,
              toolNames: ['end_turn'],
              subagents: [],
              // No paramsSchema
            },
