          issue.message.includes(
            "outputMode 'json' requires the 'set_output' tool",
          ),
        )
        expect(setOutputError).toBeDefined()
        expect(setOutputError?.message).toContain(
          "outputMode 'json' requires the 'set_output' tool",
        )
      }
    })

