        )
      }
    })

    it('should accept template with non-empty subagents and spawn_agents tool', () => {
      const template = {
        ...validBaseTemplate,
        subagents: ['researcher', 'file-picker'],
        toolNames: ['end_turn', 'spawn_agents'],
