              stepPrompt: 'Test step prompt',
              inputSchema: {
                prompt: {
                  type: 'string',
                  minLength: 1,
                  description: 'A required prompt',
                },
                params: {
                  type: 'object',
                  properties: {
                    mode: {
                      type: 'string',
