                params: {
                  type: 'object',
                  properties: {
                    message: {
                      type: 'string',
                    },
                  },
                  required: ['message'],
                },
              },
              outputMode: 'last_message',
              includeMessageHistory: true,
              toolNames: ['end_turn'],
              subagents: [],
            },
          },
