  })

  describe('Schema Validation', () => {
    describe('Default Schema Behavior', () => {
      it('should have no prompt schema when no inputSchema provided', async () => {
        const fileContext: ProjectFileContext = {
          ...mockFileContext,
          agentTemplates: {
