    // Convert to internal AgentTemplate format
    const agentTemplate: AgentTemplate = {
      ...template,
      outputSchema,
      inputSchema,
      toolNames: template.toolNames as ToolName[],
      subagents: validatedSubagents,
    }

    return {
      success: true,
      agentTemplate,
    }
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'

