          args: {
            path: `${AGENT_TEMPLATES_DIR}/example-3.ts`,
            instructions: 'Copy example 3 agent',
            content: exampleFiles[2],
          },
        }
      }
    }

    // Step 5: Let the agent ask questions and understand what the user wants
    yield 'STEP_ALL'
